// static
bool StructTraits<::speedreader::mojom::AppearanceSettings::DataView, ::speedreader::mojom::AppearanceSettingsPtr>::Read(
    ::speedreader::mojom::AppearanceSettings::DataView input,
    ::speedreader::mojom::AppearanceSettingsPtr* output) {
  bool success = true;
  ::speedreader::mojom::AppearanceSettingsPtr result(::speedreader::mojom::AppearanceSettings::New());
  
      if (success && !input.ReadTheme(&result->theme))
        success = false;
      if (success && !input.ReadFontSize(&result->fontSize))
        success = false;
      if (success && !input.ReadFontFamily(&result->fontFamily))
        success = false;
      if (success && !input.ReadColumnWidth(&result->columnWidth))
        success = false;
  *output = std::move(result);
  return success;
}


// static
bool StructTraits<::speedreader::mojom::TtsSettings::DataView, ::speedreader::mojom::TtsSettingsPtr>::Read(
    ::speedreader::mojom::TtsSettings::DataView input,
    ::speedreader::mojom::TtsSettingsPtr* output) {
  bool success = true;
  ::speedreader::mojom::TtsSettingsPtr result(::speedreader::mojom::TtsSettings::New());
  
      if (success && !input.ReadVoice(&result->voice))
        success = false;
      if (success && !input.ReadSpeed(&result->speed))
        success = false;
  *output = std::move(result);
  return success;
}


// static
bool StructTraits<::speedreader::mojom::ToolbarColors::DataView, ::speedreader::mojom::ToolbarColorsPtr>::Read(
    ::speedreader::mojom::ToolbarColors::DataView input,
    ::speedreader::mojom::ToolbarColorsPtr* output) {
  bool success = true;
  ::speedreader::mojom::ToolbarColorsPtr result(::speedreader::mojom::ToolbarColors::New());
  
      if (success)
        result->background = input.background();
      if (success)
        result->foreground = input.foreground();
      if (success)
        result->border = input.border();
      if (success)
        result->button_hover = input.button_hover();
      if (success)
        result->button_active = input.button_active();
      if (success)
        result->button_border = input.button_border();
      if (success)
        result->button_active_text = input.button_active_text();
  *output = std::move(result);
  return success;
}

